sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue === '') {
        return;
    }

    try {
        var startDate = g_form.getValue('start_date');
        var endDate = g_form.getValue('end_date');

        if (!startDate || !endDate) {
            return;
        }

        // First get the country for the user
        getCountryForUser(function(countryId) {
            // Then calculate duration with the country
            calculateDurationWithCountry(countryId);
        });
    } catch (ex) {
        console.error('Error in duration calculation:', ex);
    }

    function getCountryForUser(callback) {
        var userId = g_form.getValue('requested_by');

        var ga = new GlideAjax('HolidayAjax');
        ga.addParam('sysparm_name', 'getUserCountry');
        ga.addParam('sysparm_user_id', userId);

        ga.getXML(function(response) {
            var countryId = response.responseXML.documentElement.getAttribute("answer");
            if (countryId) {
                // Set the country field in the database
                g_form.setValue('country', countryId);
                console.log('Country set to: ' + countryId);

                if (callback) callback(countryId);
            } else {
                console.log('Could not determine country');
                if (callback) callback('');
            }
        });
    }

    function calculateDurationWithCountry(countryId) {
        var ga = new GlideAjax('HolidayAjax');
        ga.addParam('sysparm_name', 'calculateDuration');
        ga.addParam('sysparm_start_date', g_form.getValue('start_date'));
        ga.addParam('sysparm_end_date', g_form.getValue('end_date'));
        ga.addParam('sysparm_country', countryId);
        ga.addParam('sysparm_half_day', g_form.getValue('is_half_day'));

        ga.getXML(function(response) {
            var duration = response.responseXML.documentElement.getAttribute("answer");
            if (duration) {
                // Set the duration field in the database
                g_form.setValue('duration', duration);

                // Display duration message
                var durationValue = parseFloat(duration);
                var durationText = durationValue == 1 ? "1 day" : durationValue + " days";

                // Remove any existing duration messages
                var messages = g_form.getMessages();
                for (var key in messages) {
                    if (messages[key].text && messages[key].text.indexOf('Leave duration:') === 0) {
                        g_form.clearMessage(key);
                    }
                }

                // Add new duration message
                g_form.addInfoMessage("Leave duration: " + durationText);
            }
        });
    }
}
